mapper.delete:
delete from SPRING_AI_CHAT_MEMORY
where conversation_id in (
    select conversation_id from tb_ai_session_conversation where session_id = #{sessionId}
)

mapper.select:
select session_id, content, type as role, timestamp
from
    tb_ai_session_conversation as sc join SPRING_AI_CHAT_MEMORY as sacm
using (conversation_id)
where
    session_id = #{sessionId}
